using System.Collections.Generic;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "DefaultEffectAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/DefaultEffect Action")]
public class DefaultEffectAction : BattleAction
{
	[Header("Effect")]
	[SerializeField]
	protected Effect effect;

	[SerializeField]
	private bool ignoreHollowSkin;

	[SerializeField]
	private bool incorruptible;

	[SerializeField]
	private bool barrier;

	[Header("Companion")]
	[SerializeField]
	private bool checkIfACompanionIsAliveToCast;

	[SerializeField]
	[ShowIf("checkIfACompanionIsAliveToCast")]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private bool disableGainEffectSFX;

	public Effect Effect => effect;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (checkIfACompanionIsAliveToCast)
		{
			return currentCompanions.ActiveCompanions.Count > 0;
		}
		return true;
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		AreaCastTargetAmount(targets, EffectsValues.NO_VALUE, source);
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		TryEnterNoInteractionState();
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		for (int i = 0; i < targets.Count; i++)
		{
			DefaultCast(targets[i], amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		TryEnterChooseActionState();
	}

	public void AreaCastTargetNoFeedback(List<GameObject> targets, GameObject source)
	{
		AreaCastTargetAmountNoFeedback(targets, EffectsValues.NO_VALUE, source);
	}

	public void AreaCastTargetAmountNoFeedback(List<GameObject> targets, int amount, GameObject source)
	{
		TryEnterNoInteractionState();
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		for (int i = 0; i < targets.Count; i++)
		{
			DefaultCast(targets[i], amount, source, effectFeedback: false, gainingEffectVFXAndSFX: false);
		}
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		TryEnterChooseActionState();
	}

	private void TryEnterNoInteractionState()
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
	}

	private void TryEnterChooseActionState()
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		CastTargetAmount(target, EffectsValues.NO_VALUE, source);
	}

	public void CastTargetNoFeedback(GameObject target, GameObject source)
	{
		CastTargetAmountNoFeedback(target, EffectsValues.NO_VALUE, source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		TryEnterNoInteractionState();
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		DefaultCast(target, amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		TryEnterChooseActionState();
	}

	public void CastTargetAmountNoFeedback(GameObject target, int amount, GameObject source)
	{
		TryEnterNoInteractionState();
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		DefaultCast(target, amount, source, effectFeedback: false, gainingEffectVFXAndSFX: false);
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
		TryEnterChooseActionState();
	}

	public void CastTargetAmountNoGameStateChange(GameObject target, int amount, GameObject source)
	{
		amount = GetPlatinumStarLightShieldModifiedAmount(source, amount);
		DefaultCast(target, amount, source, effectFeedback: true, gainingEffectVFXAndSFX: true);
		ReferenceSingleton<MiscOmensHandler>.Instance.ResetWickedsCardOmenAction?.Invoke(source);
	}

	public virtual void DefaultCast(GameObject target, int amount, GameObject source, bool effectFeedback, bool gainingEffectVFXAndSFX)
	{
		if (incorruptible)
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorIncorruptibleLightShieldOmenAction?.Invoke();
		}
		else if (barrier)
		{
			ReferenceSingleton<HeveliusOmensHandler>.Instance.GlowingReactorBarrierLightShieldOmenAction?.Invoke();
		}
		if (amount != 0)
		{
			SpawnVFX(GetVFXOwnerPosition(target), 3f);
			target.GetComponent<UnitEffects>().AddEffect(effect, amount, effectFeedback, callEffectsCallbacks: true, source, !disableGainEffectSFX && gainingEffectVFXAndSFX, -1, ignoreHollowSkin);
			if (effectFeedback)
			{
				target.GetComponent<SpriteControl>().OnBlink();
			}
			ReferenceSingleton<MiscOmensHandler>.Instance.WickedsCardOmenAction?.Invoke(source, target);
		}
	}

	private int GetPlatinumStarLightShieldModifiedAmount(GameObject source, int amount)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayerOrCompanions(source) && ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance is DiceInstance && ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction != null && effect == source.GetComponent<UnitEffects>().EffectsList.LightShieldEffect && amount > EffectsValues.NO_VALUE)
		{
			amount = ReferenceSingleton<OrionOmensHandler>.Instance.PlatinumStarOmenAction(amount);
		}
		return amount;
	}
}
